#include <iostream>

void fijar(int& destino, int nuevo) {
    destino = nuevo;
    nuevo = nuevo + 1;
    std::cout << "Local: " << nuevo << "\n";
}

int main() {
    int destino = 2;
    const int origen = 8;
    fijar(destino, origen);
    std::cout << destino << " " << origen;
    return 0;
}

